// Changes: new, the pass state. Lives on the C stack of semantics_analyze and
// holds no heap memory, so a THROW leaks nothing (scopes are owned by AST
// nodes).
typedef struct {
  // The PROGRAM node being analysed
  AstNode* program;
  // Current scope, where a new declaration goes
  Symtable* scope;
  // The DEF whose body is being checked, NULL outside phase 2
  AstNode* def;
  // Next free slot (ir_index) of a variable of def
  size_t next_slot;
} Sema;

// Changes: new, the number of parameters of a DEF; stores its PARAM_LIST in
// *params (NULL when the DEF omits it).
static size_t def_param_list(Ctx* ctx, AstNode* def, AstNode** params) {
  *params = NULL;
  if (ast_node_get_child_count(def) <= AST_DEF_PARAM_LIST)
    return 0;
  *params = ast_node_child(ctx, def, AST_DEF_PARAM_LIST);
  return ast_node_get_child_count(*params);
}

// Changes: new, the one table of the five value types: data type, IR type and
// the spelling used in messages and member keys (ADR-0002).
typedef struct {
  AstDataType data_type;
  IrType ir_type;
  const char* name;
} TypeRow;

static const TypeRow TYPES[] = {
    {AST_DATA_TYPE_INT, IR_INT, "Int"},
    {AST_DATA_TYPE_DOUBLE, IR_DOUBLE, "Double"},
    {AST_DATA_TYPE_BOOLEAN, IR_BOOL, "Boolean"},
    {AST_DATA_TYPE_STRING, IR_STRING, "String"},
    {AST_DATA_TYPE_LIST, IR_ARRAY, "List"},
    {AST_DATA_TYPE_UNIT, IR_UNIT, "Unit"},
};
#define TYPE_COUNT (sizeof(TYPES) / sizeof(TYPES[0]))

// Changes: new, data type to the IR type stored in symbols (type table).
static IrType data_type_to_ir(Ctx* ctx, AstDataType type) {
  for (size_t i = 0; i < TYPE_COUNT; i++)
    if (TYPES[i].data_type == type)
      return TYPES[i].ir_type;
  THROW(E_INTERNAL_ERROR, "semantic analysis met an expression without a type");
  return IR_UNIT;
}

// Changes: new, a type is a base type plus a list depth (ADR-0006): Int is
// (Int, 0), List[List[Int]] is (Int, 2). Two types are the same when both
// match. A base of AST_DATA_TYPE_UNKNOWN is "no value".
typedef struct {
  AstDataType base;
  size_t depth;
} Type;

#define PLAIN(base_type) ((Type){(base_type), 0})

// Changes: new, whether two types are the same pair.
static bool same_type(Type a, Type b) {
  return a.base == b.base && a.depth == b.depth;
}

// Changes: new, the one conversion into the AST: data_type is LIST for any
// depth of at least 1, the element type holds the base, the list depth the
// depth.
static void set_node_type(AstNode* node, Type type) {
  bool list = type.depth > 0;
  ast_node_set_data_type(node, list ? AST_DATA_TYPE_LIST : type.base);
  ast_node_set_element_type(node, list ? type.base : AST_DATA_TYPE_UNKNOWN);
  ast_node_set_list_depth(node, type.depth);
}

// Changes: new, the one conversion out of the AST (see set_node_type); a node
// without a type reads as UNKNOWN.
static Type get_node_type(const AstNode* node) {
  AstDataType data_type = ast_node_get_data_type(node);
  if (data_type == AST_DATA_TYPE_LIST)
    return (Type){ast_node_get_element_type(node),
                  ast_node_get_list_depth(node)};
  return PLAIN(data_type);
}

// Changes: new, the type of a type annotation node; one without a type is an
// internal error. A TYPE_LIST gets the type of the list it spells (every level
// of a nested one), so the annotated AST shows base and depth.
// NOLINTNEXTLINE(misc-no-recursion)
static Type annotation_type(Ctx* ctx, AstNode* annotation) {
  if (ast_node_get_type(annotation) == AST_NODE_TYPE_LIST) {
    Type element = annotation_type(ctx, ast_node_child(ctx, annotation, 0));
    Type list = {element.base, element.depth + 1};
    set_node_type(annotation, list);
    return list;
  }
  if (ast_node_get_type(annotation) != AST_NODE_TYPE_ANNOTATION)
    THROW(E_INTERNAL_ERROR, "expected a type annotation at %zu:%zu",
          ast_node_get_line(annotation), ast_node_get_column(annotation));
  AstDataType type = ast_node_get_data_type(annotation);
  if (type == AST_DATA_TYPE_UNKNOWN)
    THROW(E_INTERNAL_ERROR,
          "semantic analysis met an expression without a type");
  return PLAIN(type);
}

// Changes: new, the type of the parameter at index of a PARAM_LIST.
static Type param_type(Ctx* ctx, AstNode* params, size_t index) {
  AstNode* param = ast_node_child(ctx, params, index);
  AstNode* type = ast_node_child(ctx, param, AST_PARAM_TYPE);
  return annotation_type(ctx, type);
}

// Changes: new, IR type of a symbol to the data type of an expression (type
// table).
static AstDataType ir_to_data_type(Ctx* ctx, IrType type) {
  for (size_t i = 0; i < TYPE_COUNT; i++)
    if (TYPES[i].ir_type == type)
      return TYPES[i].data_type;
  THROW(E_INTERNAL_ERROR, "semantic analysis met an unknown IR type");
  return AST_DATA_TYPE_UNKNOWN;
}

// Changes: new, the spelling of a data type in error messages (type table).
static const char* data_type_name(AstDataType type) {
  for (size_t i = 0; i < TYPE_COUNT; i++)
    if (TYPES[i].data_type == type)
      return TYPES[i].name;
  return "an unknown type";
}

// Changes: new, a type spelled for error messages (`List[Int]`), by value so
// no buffer outlives the call.
typedef struct {
  char text[64];
} TypeName;

static TypeName type_name(Type type) {
  TypeName name = {.text = ""};
  size_t used = 0;
  for (size_t i = 0; i < type.depth && used < sizeof(name.text); i++)
    used +=
        (size_t)snprintf(name.text + used, sizeof(name.text) - used, "List[");
  if (used < sizeof(name.text))
    used += (size_t)snprintf(name.text + used, sizeof(name.text) - used, "%s",
                             data_type_name(type.base));
  for (size_t i = 0; i < type.depth && used < sizeof(name.text); i++)
    used += (size_t)snprintf(name.text + used, sizeof(name.text) - used, "]");
  return name;
}

// Changes: new, the IR type stored in symbols for a type: IR_ARRAY for a list.
static IrType type_to_ir(Ctx* ctx, Type type) {
  if (type.depth > 0)
    return IR_ARRAY;
  return data_type_to_ir(ctx, type.base);
}

// Changes: new, the one conversion into a symbol (ADR-0006): ir_type, the base
// in element_type and the list depth; element_type is untouched for a plain
// value.
static void set_symbol_type(Ctx* ctx, SymtableData* symbol, Type type) {
  symbol->ir_type = type_to_ir(ctx, type);
  symbol->list_depth = type.depth;
  if (type.depth > 0)
    symbol->element_type = data_type_to_ir(ctx, type.base);
}

// Changes: new, the one conversion out of a symbol (see set_symbol_type).
static Type get_symbol_type(Ctx* ctx, const SymtableData* symbol) {
  if (symbol->list_depth > 0)
    return (Type){ir_to_data_type(ctx, symbol->element_type),
                  symbol->list_depth};
  return PLAIN(ir_to_data_type(ctx, symbol->ir_type));
}

// Changes: new, the type of the parameter at index of a function symbol.
static Type get_param_type(Ctx* ctx, const SymtableData* symbol, size_t index) {
  if (symbol->param_list_depths != NULL && symbol->param_list_depths[index] > 0)
    return (Type){ir_to_data_type(ctx, symbol->param_element_types[index]),
                  symbol->param_list_depths[index]};
  return PLAIN(ir_to_data_type(ctx, symbol->param_types[index]));
}

// Changes: new, the type of an already checked expression; an untyped one is an
// internal error.
static Type expr_type(Ctx* ctx, const AstNode* node) {
  Type type = get_node_type(node);
  if (type.base == AST_DATA_TYPE_UNKNOWN)
    THROW(E_INTERNAL_ERROR,
          "semantic analysis met an untyped expression at %zu:%zu",
          ast_node_get_line(node), ast_node_get_column(node));
  return type;
}

// Changes: new, whether from may be used where to is required: same type, or
// Int for Double.
static bool is_compatible(Type from, Type to) {
  return same_type(from, to) || (same_type(from, PLAIN(AST_DATA_TYPE_INT)) &&
                                 same_type(to, PLAIN(AST_DATA_TYPE_DOUBLE)));
}

// Changes: new, whether a type is Int or Double.
static bool is_number(Type type) {
  return type.depth == 0 &&
         (type.base == AST_DATA_TYPE_INT || type.base == AST_DATA_TYPE_DOUBLE);
}

// Changes: new, wraps the Int expression in an INT_TO_DOUBLE in its parent's
// slot (ast_node_wrap). The node stays valid, its slot now holds the wrapper.
static void widen_node(Ctx* ctx, AstNode* node) {
  if (!same_type(get_node_type(node), PLAIN(AST_DATA_TYPE_INT)))
    THROW(E_INTERNAL_ERROR, "only an Int can be widened, at %zu:%zu",
          ast_node_get_line(node), ast_node_get_column(node));
  AstNode* wrapper = ast_node_wrap(ctx, node, AST_NODE_INT_TO_DOUBLE);
  set_node_type(wrapper, PLAIN(AST_DATA_TYPE_DOUBLE));
}

// Changes: new, the checked expression must fit target: same type passes, Int
// is widened to Double in place, anything else stops with code (6 values, 5
// arguments); what names the construct in the message.
static void require_compatible(Ctx* ctx,
                               AstNode* node,
                               Type target,
                               ExitCode code,
                               const char* what) {
  Type actual = expr_type(ctx, node);
  if (!is_compatible(actual, target))
    THROW(code, "%s at %zu:%zu needs %s but the value is %s", what,
          ast_node_get_line(node), ast_node_get_column(node),
          type_name(target).text, type_name(actual).text);
  if (!same_type(actual, target))
    widen_node(ctx, node);
}

// Changes: new, the expression must be a Boolean (exit 6), nothing is widened.
static void require_boolean(Ctx* ctx, AstNode* node, const char* what) {
  Type actual = expr_type(ctx, node);
  if (!same_type(actual, PLAIN(AST_DATA_TYPE_BOOLEAN)))
    THROW(E_SEMANTIC_TYPE_ERROR, "%s at %zu:%zu must be Boolean but is %s",
          what, ast_node_get_line(node), ast_node_get_column(node),
          type_name(actual).text);
}

// Changes: new, the data of a function symbol. The parameter array (NULL for
// none) is owned by the symtable once inserted; nothing may THROW between
// filling and inserting it.
static SymtableData function_data(Ctx* ctx,
                                  Type return_type,
                                  size_t ir_index,
                                  size_t param_count) {
  SymtableData data = {
      .symbol_type = SYMBOL_FUNCTION,
      .ir_index = ir_index,
      .param_count = param_count,
      .param_types = NULL,
      .param_element_types = NULL,
      .param_list_depths = NULL,
      .element_type = IR_INT,
      .list_depth = 0,
      .is_val = false,
  };
  set_symbol_type(ctx, &data, return_type);
  if (param_count > 0) {
    data.param_types = TRY_MALLOC(sizeof(IrType) * param_count);
    data.param_element_types = TRY_MALLOC_OR(sizeof(IrType) * param_count,
                                             { free(data.param_types); });
    data.param_list_depths = TRY_MALLOC_OR(sizeof(size_t) * param_count, {
      free(data.param_types);
      free(data.param_element_types);
    });
    for (size_t i = 0; i < param_count; i++) {
      data.param_element_types[i] = IR_INT;
      data.param_list_depths[i] = 0;
    }
  }
  return data;
}

// Changes: new, phase 0: inserts the member entries "<ReceiverType>.<member>"
// (ADR-0002), "Range.toList", "List", "List::range" and the "List.<member>"
// entries into the global scope.
static void insert_members(Ctx* ctx, Sema* sema) {
  static const struct {
    const char* key;
    IrType receiver;
    IrType result;
    IrFunctionType function;
  } members[] = {
      {"Int.toString", IR_INT, IR_STRING, IR_FX_TO_STR},
      {"Double.toString", IR_DOUBLE, IR_STRING, IR_FX_TO_STR},
      {"Boolean.toString", IR_BOOL, IR_STRING, IR_FX_TO_STR},
      {"String.toString", IR_STRING, IR_STRING, IR_FX_TO_STR},
      {"Unit.toString", IR_UNIT, IR_STRING, IR_FX_TO_STR},
      {"Double.toInt", IR_DOUBLE, IR_INT, IR_FX_TO_INT},
      // The IR has a floor instruction instead of a function, ir_index is
      // unused and IR generation recognises the member by its name
      {"Double.floor", IR_DOUBLE, IR_DOUBLE, IR_FX_USER},
      {"String.length", IR_STRING, IR_INT, IR_FX_STR_LEN},
  };
  for (size_t i = 0; i < sizeof(members) / sizeof(members[0]); i++) {
    SymtableData data =
        function_data(ctx, PLAIN(ir_to_data_type(ctx, members[i].result)),
                      (size_t)members[i].function, 1);
    data.param_types[0] = members[i].receiver;
    symtable_insert(ctx, sema->scope, (char*)members[i].key, data);
  }

  // A range value has no IR type of its own, its only member is toList
  SymtableData to_list = function_data(ctx, (Type){AST_DATA_TYPE_INT, 1},
                                       (size_t)IR_FX_RANGE_TO_LIST, 1);
  // The Int stands for a range receiver and is never read
  to_list.param_types[0] = IR_INT;
  symtable_insert(ctx, sema->scope, "Range.toList", to_list);

  // The list creation, no parameters: the elements are checked per CALL. Its
  // return type is not read: the result comes from the elements.
  SymtableData list =
      function_data(ctx, (Type){AST_DATA_TYPE_INT, 1}, IR_FX_LIST_CREATE, 0);
  symtable_insert(ctx, sema->scope, "List", list);

  // List.range(a, b[, step]): the key "List::range" is a symtable key only, no
  // member lookup can build it (ADR-0002); the step is optional
  SymtableData range =
      function_data(ctx, (Type){AST_DATA_TYPE_INT, 1}, IR_FX_LIST_RANGE, 3);
  for (size_t i = 0; i < 3; i++)
    range.param_types[i] = IR_INT;
  symtable_insert(ctx, sema->scope, "List::range", range);

  // The list members, the receiver is the first parameter (ADR-0002); ir_type
  // encodes the result: IR_ARRAY the receiver's own type, IR_UNIT its element
  // type, anything else itself. The List[Int] in the
  // result column is a placeholder that only fixes ir_type and is never read
  // as the result's list depth
  static const struct {
    const char* key;
    Type result;
    IrFunctionType function;
    size_t param_count;
  } list_members[] = {
      {"List.head", {AST_DATA_TYPE_UNIT, 0}, IR_FX_LIST_HEAD, 1},
      {"List.tail", {AST_DATA_TYPE_INT, 1}, IR_FX_LIST_TAIL, 1},
      {"List.toString", {AST_DATA_TYPE_STRING, 0}, IR_FX_LIST_TO_STR, 1},
      {"List.drop", {AST_DATA_TYPE_INT, 1}, IR_FX_LIST_DROP, 2},
      {"List.take", {AST_DATA_TYPE_INT, 1}, IR_FX_LIST_TAKE, 2},
      {"List.slice", {AST_DATA_TYPE_INT, 1}, IR_FX_LIST_SLICE, 3},
  };
  for (size_t i = 0; i < sizeof(list_members) / sizeof(list_members[0]); i++) {
    SymtableData data = function_data(ctx, list_members[i].result,
                                      (size_t)list_members[i].function,
                                      list_members[i].param_count);
    data.param_types[0] = IR_ARRAY;
    for (size_t j = 1; j < list_members[i].param_count; j++)
      data.param_types[j] = IR_INT;
    symtable_insert(ctx, sema->scope, (char*)list_members[i].key, data);
  }
}

// Changes: new, declares one DEF as a global function symbol. A name already
// global is exit 4, an omitted return type is a Unit placeholder until
// inferred, a @main with a parameter is exit 5.
static void collect_function(Ctx* ctx, Sema* sema, AstNode* def, size_t id) {
  AstNode* ident = ast_node_child(ctx, def, AST_DEF_IDENT);
  const char* name = ast_node_get_name(ident);

  if (symtable_lookup(sema->scope, (char*)name, false) != NULL)
    THROW(E_SEMANTIC_REDEFINITION_ERROR,
          "redefinition of function '%s' at %zu:%zu", name,
          ast_node_get_line(ident), ast_node_get_column(ident));

  AstNode* rettype = ast_node_child(ctx, def, AST_DEF_RETTYPE);
  Type return_type = PLAIN(AST_DATA_TYPE_UNIT);
  if (ast_node_get_type(rettype) != AST_NODE_NONE)
    return_type = annotation_type(ctx, rettype);

  AstNode* params = NULL;
  size_t param_count = def_param_list(ctx, def, &params);

  if ((ast_node_get_flags(def) & (unsigned)AST_FLAG_MAIN) && param_count > 0)
    THROW(E_SEMANTIC_ARGUMENT_ERROR,
          "@main function '%s' at %zu:%zu must not have parameters", name,
          ast_node_get_line(ident), ast_node_get_column(ident));

  // Check every parameter type before allocating the array, so a THROW here
  // has nothing to free
  for (size_t i = 0; i < param_count; i++)
    (void)param_type(ctx, params, i);
  SymtableData data = function_data(ctx, return_type, id, param_count);
  for (size_t i = 0; i < param_count; i++) {
    Type type = param_type(ctx, params, i);
    data.param_types[i] = type_to_ir(ctx, type);
    data.param_list_depths[i] = type.depth;
    if (type.depth > 0)
      data.param_element_types[i] = data_type_to_ir(ctx, type.base);
  }

  symtable_insert(ctx, sema->scope, (char*)name, data);
  ast_node_set_symbol(ident, symtable_lookup(sema->scope, (char*)name, false));
}

// Changes: new, declares one DEF as a global function symbol. A name already
// global is exit 4, an omitted return type is a Unit placeholder until
// inferred, a @main with a parameter is exit 5.
static void collect_functions(Ctx* ctx, Sema* sema) {
  size_t mains = 0;
  size_t count = ast_node_get_child_count(sema->program);
  for (size_t id = 0; id < count; id++) {
    AstNode* def = ast_node_child(ctx, sema->program, id);
    if (ast_node_get_type(def) != AST_NODE_DEF)
      THROW(E_INTERNAL_ERROR, "unexpected top-level node at %zu:%zu",
            ast_node_get_line(def), ast_node_get_column(def));

    if (ast_node_get_flags(def) & (unsigned)AST_FLAG_MAIN) {
      mains++;
      if (mains > 1) {
        AstNode* ident = ast_node_child(ctx, def, AST_DEF_IDENT);
        THROW(E_SEMANTIC_REDEFINITION_ERROR,
              "more than one @main function, second one '%s' at %zu:%zu",
              ast_node_get_name(ident), ast_node_get_line(ident),
              ast_node_get_column(ident));
      }
    }

    collect_function(ctx, sema, def, id);
  }
  if (mains == 0)
    THROW(E_SEMANTIC_UNDEFINED_ERROR, "no @main function in the program");
}

// Changes: new, declares a parameter, val, var or for variable in the current
// scope. A name already in that scope is exit 4, checked before the insert so
// no symbol an AST node points at is replaced.
static void declare_variable(Ctx* ctx,
                             Sema* sema,
                             AstNode* ident,
                             Type type,
                             bool is_val,
                             size_t slot) {
  const char* name = ast_node_get_name(ident);
  if (symtable_lookup(sema->scope, (char*)name, false) != NULL)
    THROW(E_SEMANTIC_REDEFINITION_ERROR, "redefinition of '%s' at %zu:%zu",
          name, ast_node_get_line(ident), ast_node_get_column(ident));

  SymtableData data = {
      .symbol_type = SYMBOL_VARIABLE,
      .ir_index = slot,
      .param_count = 0,
      .param_types = NULL,
      .param_element_types = NULL,
      .param_list_depths = NULL,
      .is_val = is_val,
  };
  set_symbol_type(ctx, &data, type);
  symtable_insert(ctx, sema->scope, (char*)name, data);
  ast_node_set_symbol(ident, symtable_lookup(sema->scope, (char*)name, false));
}

// Changes: new, resolves an identifier to a visible variable, from the current
// scope outward; none is exit 3.
static SymtableData* resolve_variable(Ctx* ctx, Sema* sema, AstNode* ident) {
  const char* name = ast_node_get_name(ident);
  SymtableData* symbol = symtable_lookup(sema->scope, (char*)name, true);
  if (symbol == NULL || symbol->symbol_type != SYMBOL_VARIABLE)
    THROW(E_SEMANTIC_UNDEFINED_ERROR, "undefined variable '%s' at %zu:%zu",
          name, ast_node_get_line(ident), ast_node_get_column(ident));
  ast_node_set_symbol(ident, symbol);
  return symbol;
}

// Changes: new, resolves a callee that names no visible variable among the
// global functions; none is exit 3.
static SymtableData* resolve_function(Ctx* ctx, AstNode* ident) {
  const char* name = ast_node_get_name(ident);
  // The lookup key: only List.range is a function, any other List.<name> none
  const char* key = name;
  if (strcmp(name, "List.range") == 0)
    key = "List::range";
  else if (strncmp(name, "List.", 5) == 0)
    key = "";
  SymtableData* symbol =
      symtable_lookup(&ctx->global_symtable, (char*)key, false);
  if (symbol == NULL || symbol->symbol_type != SYMBOL_FUNCTION)
    THROW(E_SEMANTIC_UNDEFINED_ERROR, "undefined function '%s' at %zu:%zu",
          name, ast_node_get_line(ident), ast_node_get_column(ident));
  ast_node_set_symbol(ident, symbol);
  return symbol;
}

// Changes: new, marks a node as a built-in (the BUILTIN flag).
static void mark_builtin(AstNode* node) {
  ast_node_set_flags(node,
                     ast_node_get_flags(node) | (unsigned)AST_FLAG_BUILTIN);
}

// Changes: new, binds a MEMBER node to its built-in entry and gives it its
// type.
static void bind_builtin_member(AstNode* node,
                                const SymtableData* symbol,
                                Type type) {
  ast_node_set_symbol(node, symbol);
  mark_builtin(node);
  set_node_type(node, type);
}

// Changes: new, the DEF of a user function symbol, NULL for a built-in or
// member (the built-in test).
static AstNode* def_of_symbol(Ctx* ctx,
                              const Sema* sema,
                              const SymtableData* symbol) {
  if (symbol->ir_index >= ast_node_get_child_count(sema->program))
    return NULL;
  AstNode* def = ast_node_child(ctx, sema->program, symbol->ir_index);
  AstNode* ident = ast_node_child(ctx, def, AST_DEF_IDENT);
  return ast_node_get_symbol(ident) == symbol ? def : NULL;
}

static void check_stmt(Ctx* ctx, Sema* sema, AstNode* node);
static void check_expr(Ctx* ctx, Sema* sema, AstNode* node);
static void check_def(Ctx* ctx, Sema* sema, AstNode* def);
static void check_expr_as(Ctx* ctx, Sema* sema, AstNode* node, Type expected);

// Changes: new, "no expected type" (ADR-0007): a base of UNKNOWN. Only a list
// type (depth of at least 1) is ever used as an expected type.
#define NO_EXPECTED PLAIN(AST_DATA_TYPE_UNKNOWN)

// Changes: new, checks every child of node from index first as an expression.
static void check_expr_children(Ctx* ctx,
                                Sema* sema,
                                AstNode* node,
                                size_t first) {
  size_t count = ast_node_get_child_count(node);
  for (size_t i = first; i < count; i++) {
    AstNode* child = ast_node_child(ctx, node, i);
    check_expr(ctx, sema, child);
  }
}

// Changes: new, a VAL or VAR. The initializer is checked before the declaration
// (it still sees a shadowed outer name); it gives the type, or must fit the
// annotation (exit 6), which is its expected type.
static void check_val_var(Ctx* ctx, Sema* sema, AstNode* node) {
  AstNode* ident = ast_node_child(ctx, node, AST_VAL_IDENT);
  AstNode* annotation = ast_node_child(ctx, node, AST_VAL_TYPE);
  AstNode* init = ast_node_child(ctx, node, AST_VAL_INIT);

  Type type = PLAIN(AST_DATA_TYPE_UNIT);
  if (ast_node_get_type(annotation) != AST_NODE_NONE) {
    type = annotation_type(ctx, annotation);
    check_expr_as(ctx, sema, init, type);
    require_compatible(ctx, init, type, E_SEMANTIC_TYPE_ERROR, "initializer");
  } else {
    check_expr(ctx, sema, init);
    type = expr_type(ctx, init);
  }
  declare_variable(ctx, sema, ident, type,
                   ast_node_get_type(node) == AST_NODE_VAL, sema->next_slot++);
}

// Changes: new, the ASSIGN target must be a visible writable variable: a val,
// parameter or for variable, and any name that is no visible variable, is exit
// 7 (PDF 2.2).
static void check_assign_target(Ctx* ctx, Sema* sema, AstNode* target) {
  const char* name = ast_node_get_name(target);
  SymtableData* symbol = symtable_lookup(sema->scope, (char*)name, true);
  if (symbol == NULL || symbol->symbol_type != SYMBOL_VARIABLE)
    THROW(E_SEMANTIC_REWRITE_ERROR,
          "assignment to '%s' at %zu:%zu, which is no defined variable", name,
          ast_node_get_line(target), ast_node_get_column(target));
  ast_node_set_symbol(target, symbol);
  if (symbol->is_val)
    THROW(E_SEMANTIC_REWRITE_ERROR,
          "assignment to the read-only variable '%s' at %zu:%zu",
          ast_node_get_name(target), ast_node_get_line(target),
          ast_node_get_column(target));
}

// Changes: new, an ASSIGN: writable target, then a value compatible with its
// type (exit 6), which is the value's expected type.
static void check_assign(Ctx* ctx, Sema* sema, AstNode* node) {
  AstNode* target = ast_node_child(ctx, node, AST_ASSIGN_IDENT);
  AstNode* value = ast_node_child(ctx, node, AST_ASSIGN_VALUE);
  check_assign_target(ctx, sema, target);
  const SymtableData* symbol = ast_node_get_symbol(target);
  check_expr_as(ctx, sema, value, get_symbol_type(ctx, symbol));
  require_compatible(ctx, value, get_symbol_type(ctx, symbol),
                     E_SEMANTIC_TYPE_ERROR, "assigned value");
}

// Changes: new, how a position treats the value of a block's last statement.
// A ResultRule says how a position treats the value of the last statement of a
// block, and of each branch of an `if` ending it:
//  - declared: the position states its type (a function body with a declared
//    return type). Every path must end in a return or a compatible value (Int
//    widened to Double); a declared Unit discards every value.
//  - not declared: the type is whatever the value has (omitted return type, if
//    expression); the branches of an `if` need one common type, Int and Double
//    give Double.
//  - else_required: a missing else is exit 6 (an if expression). Without it a
//    missing else counts as a `()` branch.
// A branch ending in `return` yields no value (AST_DATA_TYPE_UNKNOWN) and takes
// the other branch's type. A NULL rule means the value is discarded.
typedef struct {
  bool declared;
  Type type;
  bool else_required;
  Type expected;  // not declared: the expected type of the value (ADR-0007)
} ResultRule;

// Changes: new, the rule of an if expression: no declared type, a missing else
// is exit 6, both branches receive the expected type (NO_EXPECTED for none).
static ResultRule if_expression_rule(Type expected) {
  return (ResultRule){.declared = false,
                      .type = NO_EXPECTED,
                      .else_required = true,
                      .expected = expected};
}

// Changes: new, the expected type a rule passes to the value of its position:
// the declared type, or the one an if expression was given.
static Type rule_expected(const ResultRule* rule) {
  return rule->declared ? rule->type : rule->expected;
}

// Changes: new, the body result rule of a DEF, the one place that knows whether
// a function declares its return type.
static ResultRule body_rule(Ctx* ctx, AstNode* def) {
  AstNode* rettype = ast_node_child(ctx, def, AST_DEF_RETTYPE);
  ResultRule rule = {.declared = false,
                     .type = {AST_DATA_TYPE_UNIT, 0},
                     .else_required = false,
                     .expected = NO_EXPECTED};
  if (ast_node_get_type(rettype) != AST_NODE_NONE) {
    rule.declared = true;
    rule.type = annotation_type(ctx, rettype);
  }
  return rule;
}

// Changes: new, a RETURN. Its value is checked first (exit 3 wins) with the
// declared return type as expected type; without a declared return type any
// return is exit 6, a declared Unit discards the value, any other type needs a
// compatible value.
static void check_return(Ctx* ctx, Sema* sema, AstNode* node) {
  AstNode* value = ast_node_child(ctx, node, AST_RETURN_VALUE);
  bool has_value = ast_node_get_type(value) != AST_NODE_NONE;
  ResultRule rule = body_rule(ctx, sema->def);
  if (has_value)
    check_expr_as(ctx, sema, value, rule_expected(&rule));

  if (!rule.declared)
    THROW(E_SEMANTIC_TYPE_ERROR,
          "return at %zu:%zu in a function without a declared return type",
          ast_node_get_line(node), ast_node_get_column(node));
  if (same_type(rule.type, PLAIN(AST_DATA_TYPE_UNIT)))
    return;
  if (!has_value)
    THROW(E_SEMANTIC_TYPE_ERROR,
          "bare return at %zu:%zu in a function returning %s",
          ast_node_get_line(node), ast_node_get_column(node),
          type_name(rule.type).text);
  require_compatible(ctx, value, rule.type, E_SEMANTIC_TYPE_ERROR,
                     "returned value");
}

// Changes: new, whether the rule asks for a value of a declared non-Unit type.
static bool must_yield_value(const ResultRule* rule) {
  return rule->declared && !same_type(rule->type, PLAIN(AST_DATA_TYPE_UNIT));
}

// Changes: new, whether a missing else is exit 6 under the rule.
static bool needs_else(const ResultRule* rule) {
  return rule->declared ? must_yield_value(rule) : rule->else_required;
}

// Changes: new, whether a statement kind yields Unit at the end of a block (a
// return yields no value).
static bool is_unit_statement(AstNodeType type) {
  return type == AST_NODE_VAL || type == AST_NODE_VAR ||
         type == AST_NODE_ASSIGN || type == AST_NODE_WHILE ||
         type == AST_NODE_FOR;
}

// Changes: new, widens what a branch of an if expression yields: the last
// statement of a BLOCK, both branches of an else-if IF, or an Int expression
// (wrapped in place). A branch without a value is left alone.
// NOLINTNEXTLINE(misc-no-recursion)
static void widen_branch(Ctx* ctx, AstNode* node) {
  switch (ast_node_get_type(node)) {
    case AST_NODE_BLOCK:
      if (ast_node_get_child_count(node) > 0)
        widen_branch(
            ctx, ast_node_child(ctx, node, ast_node_get_child_count(node) - 1));
      break;
    case AST_NODE_IF:
      widen_branch(ctx, ast_node_child(ctx, node, AST_IF_THEN));
      widen_branch(ctx, ast_node_child(ctx, node, AST_IF_ELSE));
      set_node_type(node, PLAIN(AST_DATA_TYPE_DOUBLE));
      break;
    case AST_NODE_NONE:
    case AST_NODE_RETURN:
      break;
    default:
      widen_node(ctx, node);
      break;
  }
}

// Changes: new, the common type of the two branches of an `if` under a rule. No
// value on both sides is UNKNOWN, a declared type wins, a valueless branch
// takes the other's type, Int with Double gives Double; anything else is exit
// 6.
static Type unify_branches(Ctx* ctx,
                           AstNode* node,
                           const ResultRule* rule,
                           Type then_type,
                           Type else_type) {
  Type none = PLAIN(AST_DATA_TYPE_UNKNOWN);
  if (same_type(then_type, none) && same_type(else_type, none))
    return none;
  if (rule->declared)
    return rule->type;
  if (same_type(then_type, none))
    return else_type;
  if (same_type(else_type, none) || same_type(then_type, else_type))
    return then_type;
  if (!is_number(then_type) || !is_number(else_type))
    THROW(E_SEMANTIC_TYPE_ERROR,
          "branches of the if at %zu:%zu have different types %s and %s",
          ast_node_get_line(node), ast_node_get_column(node),
          type_name(then_type).text, type_name(else_type).text);
  size_t int_side =
      then_type.base == AST_DATA_TYPE_INT ? AST_IF_THEN : AST_IF_ELSE;
  widen_branch(ctx, ast_node_child(ctx, node, int_side));
  return PLAIN(AST_DATA_TYPE_DOUBLE);
}

static Type check_result_stmt(Ctx* ctx,
                              Sema* sema,
                              AstNode* stmt,
                              const ResultRule* rule);
static Type check_block(Ctx* ctx,
                        Sema* sema,
                        AstNode* block,
                        const ResultRule* rule);

// Changes: new, checks a branch of an IF under the rule and returns what it
// yields (NULL rule: a statement, Unit).
static Type check_branch(Ctx* ctx,
                         Sema* sema,
                         AstNode* branch,
                         const ResultRule* rule) {
  if (rule != NULL)
    return check_result_stmt(ctx, sema, branch, rule);
  check_stmt(ctx, sema, branch);
  return PLAIN(AST_DATA_TYPE_UNIT);
}

// Changes: new, checks an IF under the rule (NULL: a statement, the IF is
// Unit). Boolean condition in the enclosing scope, the branches (else if by
// recursion), the missing else rule and unify_branches. Returns UNKNOWN when
// every branch returns.
// NOLINTNEXTLINE(misc-no-recursion)
static Type check_if_node(Ctx* ctx,
                          Sema* sema,
                          AstNode* node,
                          const ResultRule* rule) {
  AstNode* cond = ast_node_child(ctx, node, AST_IF_COND);
  AstNode* else_branch = ast_node_child(ctx, node, AST_IF_ELSE);
  check_expr(ctx, sema, cond);
  require_boolean(ctx, cond, "condition of if");

  AstNode* then_branch = ast_node_child(ctx, node, AST_IF_THEN);
  Type then_type = check_branch(ctx, sema, then_branch, rule);
  Type else_type = PLAIN(AST_DATA_TYPE_UNIT);
  switch (ast_node_get_type(else_branch)) {
    case AST_NODE_NONE:
      if (rule != NULL && needs_else(rule))
        THROW(E_SEMANTIC_TYPE_ERROR, "if at %zu:%zu has no else but needs a %s",
              ast_node_get_line(node), ast_node_get_column(node),
              rule->declared ? type_name(rule->type).text : "value");
      break;
    case AST_NODE_IF:
      else_type = check_if_node(ctx, sema, else_branch, rule);
      break;
    default:
      else_type = check_branch(ctx, sema, else_branch, rule);
      break;
  }

  Type result = PLAIN(AST_DATA_TYPE_UNIT);
  if (rule != NULL)
    result = unify_branches(ctx, node, rule, then_type, else_type);
  set_node_type(node, result.base == AST_DATA_TYPE_UNKNOWN
                          ? PLAIN(AST_DATA_TYPE_UNIT)
                          : result);
  return result;
}

// Changes: new, an IF reached as a statement or expression: EXPR-flagged ones
// are checked as an if expression, others as statements.
static void check_if(Ctx* ctx, Sema* sema, AstNode* node) {
  bool as_expr = (ast_node_get_flags(node) & (unsigned)AST_FLAG_EXPR) != 0;
  ResultRule rule = if_expression_rule(NO_EXPECTED);
  (void)check_if_node(ctx, sema, node, as_expr ? &rule : NULL);
}

// Changes: new, checks the last statement under the rule and returns what it
// yields: BLOCK/IF by recursion, return UNKNOWN, val/var/assign/while/for Unit,
// an expression its type, widened in place to a declared type; the rule's
// expected type goes to the expression.
// NOLINTNEXTLINE(misc-no-recursion)
static Type check_result_stmt(Ctx* ctx,
                              Sema* sema,
                              AstNode* stmt,
                              const ResultRule* rule) {
  AstNodeType kind = ast_node_get_type(stmt);
  if (kind == AST_NODE_BLOCK)
    return check_block(ctx, sema, stmt, rule);
  if (kind == AST_NODE_IF) {
    if (ast_node_get_flags(stmt) & (unsigned)AST_FLAG_EXPR) {
      ResultRule inner = if_expression_rule(rule_expected(rule));
      Type type = check_if_node(ctx, sema, stmt, &inner);
      if (type.base == AST_DATA_TYPE_UNKNOWN || !rule->declared)
        return type;
      if (must_yield_value(rule))
        require_compatible(ctx, stmt, rule->type, E_SEMANTIC_TYPE_ERROR,
                           "result of the function");
      return rule->type;
    }
    ResultRule nested = *rule;
    nested.else_required = false;
    return check_if_node(ctx, sema, stmt, &nested);
  }
  if (kind == AST_NODE_RETURN) {
    check_stmt(ctx, sema, stmt);
    return PLAIN(AST_DATA_TYPE_UNKNOWN);
  }
  if (is_unit_statement(kind)) {
    check_stmt(ctx, sema, stmt);
    if (must_yield_value(rule))
      THROW(E_SEMANTIC_TYPE_ERROR,
            "statement at %zu:%zu ends a function that must return %s",
            ast_node_get_line(stmt), ast_node_get_column(stmt),
            type_name(rule->type).text);
    return PLAIN(AST_DATA_TYPE_UNIT);
  }
  check_expr_as(ctx, sema, stmt, rule_expected(rule));
  if (!rule->declared)
    return expr_type(ctx, stmt);
  if (must_yield_value(rule))
    require_compatible(ctx, stmt, rule->type, E_SEMANTIC_TYPE_ERROR,
                       "result of the function");
  return rule->type;
}

// Changes: new, a BLOCK in its own nested scope (kept by the BLOCK). With a
// rule its last statement goes through check_result_stmt and the block yields
// its type; an empty block yields Unit.
// NOLINTNEXTLINE(misc-no-recursion)
static Type check_block(Ctx* ctx,
                        Sema* sema,
                        AstNode* block,
                        const ResultRule* rule) {
  Symtable* outer = sema->scope;
  sema->scope = ast_node_attach_scope(ctx, block, outer);
  size_t count = ast_node_get_child_count(block);
  if (rule != NULL && count == 0 && must_yield_value(rule))
    THROW(E_SEMANTIC_TYPE_ERROR,
          "empty block at %zu:%zu in a function that must return %s",
          ast_node_get_line(block), ast_node_get_column(block),
          type_name(rule->type).text);
  Type result = PLAIN(AST_DATA_TYPE_UNIT);
  for (size_t i = 0; i < count; i++) {
    if (rule != NULL && i + 1 == count) {
      AstNode* last = ast_node_child(ctx, block, i);
      result = check_result_stmt(ctx, sema, last, rule);
    } else {
      AstNode* stmt = ast_node_child(ctx, block, i);
      check_stmt(ctx, sema, stmt);
    }
  }
  sema->scope = outer;
  return result;
}

// Changes: new, a WHILE: Boolean condition in the enclosing scope, body in its
// own scope.
static void check_while(Ctx* ctx, Sema* sema, AstNode* node) {
  AstNode* cond = ast_node_child(ctx, node, AST_WHILE_COND);
  AstNode* body = ast_node_child(ctx, node, AST_WHILE_BODY);
  check_expr(ctx, sema, cond);
  require_boolean(ctx, cond, "condition of while");
  check_stmt(ctx, sema, body);
}

// Changes: new, whether node is the literal Int 0 or -0, the only steps
// rejected at compile time.
static bool is_zero_literal(Ctx* ctx, AstNode* node) {
  if (ast_node_get_type(node) == AST_NODE_NEG &&
      ast_node_get_child_count(node) == 1) {
    AstNode* operand = ast_node_child(ctx, node, AST_UNARY_OPERAND);
    node = operand;
  }
  return ast_node_get_type(node) == AST_NODE_INT_LIT &&
         ast_node_get_value(node).int_value == 0;
}

// Changes: new, a RANGE_TO or RANGE_UNTIL: Int bounds and step (exit 6); a
// literal 0 or -0 step is exit 10.
static void check_range(Ctx* ctx, Sema* sema, AstNode* node) {
  size_t count = ast_node_get_child_count(node);
  for (size_t i = 0; i < count; i++) {
    AstNode* child = ast_node_child(ctx, node, i);
    if (ast_node_get_type(child) == AST_NODE_NONE)
      continue;
    check_expr(ctx, sema, child);
    Type actual = expr_type(ctx, child);
    if (!same_type(actual, PLAIN(AST_DATA_TYPE_INT)))
      THROW(E_SEMANTIC_TYPE_ERROR,
            "%s of a range at %zu:%zu must be Int but is %s",
            i == AST_RANGE_STEP ? "step" : "bound", ast_node_get_line(child),
            ast_node_get_column(child), type_name(actual).text);
    if (i == AST_RANGE_STEP && is_zero_literal(ctx, child))
      THROW(E_SEMANTIC_OTHER_ERROR, "step of a range at %zu:%zu is zero",
            ast_node_get_line(child), ast_node_get_column(child));
  }
}

// Changes: new, whether the node is a range value (RANGE_TO or RANGE_UNTIL).
static bool is_range(const AstNode* node) {
  return ast_node_get_type(node) == AST_NODE_RANGE_TO ||
         ast_node_get_type(node) == AST_NODE_RANGE_UNTIL;
}

// Changes: new, a FOR: source in the enclosing scope (a range value or a
// list), a loop-variable scope (owned by the FOR) with the read-only loop
// variable (Int for a range, the element type of a list, a non-list source is
// exit 6), Boolean guards in it, the body scope nested inside.
static void check_for(Ctx* ctx, Sema* sema, AstNode* node) {
  AstNode* ident = ast_node_child(ctx, node, AST_FOR_IDENT);
  AstNode* source = ast_node_child(ctx, node, AST_FOR_SOURCE);
  AstNode* body = ast_node_child(ctx, node, AST_FOR_BODY);

  if (is_range(source))
    check_range(ctx, sema, source);
  else
    check_expr(ctx, sema, source);

  Type variable = PLAIN(AST_DATA_TYPE_INT);
  if (!is_range(source)) {
    Type list = expr_type(ctx, source);
    if (list.depth == 0)
      THROW(E_SEMANTIC_TYPE_ERROR,
            "source of for at %zu:%zu must be a list but is %s",
            ast_node_get_line(source), ast_node_get_column(source),
            type_name(list).text);
    variable = (Type){list.base, list.depth - 1};
  }

  Symtable* outer = sema->scope;
  sema->scope = ast_node_attach_scope(ctx, node, outer);
  declare_variable(ctx, sema, ident, variable, true, sema->next_slot++);
  set_node_type(ident, variable);
  size_t count = ast_node_get_child_count(node);
  for (size_t i = AST_FOR_FIRST_GUARD; i < count; i++) {
    AstNode* guard = ast_node_child(ctx, node, i);
    check_expr(ctx, sema, guard);
    require_boolean(ctx, guard, "guard of for");
  }
  check_stmt(ctx, sema, body);
  sema->scope = outer;
}

// Changes: new, an IDENT used as a value takes the type of its variable symbol;
// a bare List.range is exit 5.
static void check_ident(Ctx* ctx, Sema* sema, AstNode* node) {
  if (strcmp(ast_node_get_name(node), "List.range") == 0)
    THROW(E_SEMANTIC_ARGUMENT_ERROR,
          "List.range at %zu:%zu needs an argument list",
          ast_node_get_line(node), ast_node_get_column(node));
  const SymtableData* symbol = resolve_variable(ctx, sema, node);
  set_node_type(node, get_symbol_type(ctx, symbol));
}

// Changes: new, a literal has the type of its kind.
static void check_literal(Ctx* ctx, Sema* sema, AstNode* node) {
  (void)sema;
  switch (ast_node_get_type(node)) {
    case AST_NODE_INT_LIT:
      ast_node_set_data_type(node, AST_DATA_TYPE_INT);
      break;
    case AST_NODE_DOUBLE_LIT:
      ast_node_set_data_type(node, AST_DATA_TYPE_DOUBLE);
      break;
    case AST_NODE_STRING_LIT:
      ast_node_set_data_type(node, AST_DATA_TYPE_STRING);
      break;
    case AST_NODE_BOOL_LIT:
      ast_node_set_data_type(node, AST_DATA_TYPE_BOOLEAN);
      break;
    case AST_NODE_UNIT_LIT:
      ast_node_set_data_type(node, AST_DATA_TYPE_UNIT);
      break;
    default:
      THROW(E_INTERNAL_ERROR, "expected a literal at %zu:%zu",
            ast_node_get_line(node), ast_node_get_column(node));
  }
}

// Changes: new, the spelling of an operator node in error messages.
static const char* operator_name(AstNodeType type) {
  switch (type) {
    case AST_NODE_ADD:
      return "+";
    case AST_NODE_SUB:
      return "-";
    case AST_NODE_MUL:
      return "*";
    case AST_NODE_DIV:
      return "/";
    case AST_NODE_EQ:
      return "==";
    case AST_NODE_NEQ:
      return "!=";
    case AST_NODE_LT:
      return "<";
    case AST_NODE_GT:
      return ">";
    case AST_NODE_LE:
      return "<=";
    case AST_NODE_GE:
      return ">=";
    case AST_NODE_AND:
      return "&&";
    case AST_NODE_OR:
      return "||";
    case AST_NODE_NOT:
      return "!";
    case AST_NODE_NEG:
      return "-";
    case AST_NODE_CONCAT:
      return "++";
    default:
      return "operator";
  }
}

// Changes: new, exit 6 for operands an operator does not accept, naming the
// operator and the operand types.
static void operand_error(Ctx* ctx,
                          const AstNode* node,
                          Type left,
                          Type right) {
  if (ast_node_get_child_count(node) == 1)
    THROW(E_SEMANTIC_TYPE_ERROR,
          "operator '%s' at %zu:%zu cannot be applied to %s",
          operator_name(ast_node_get_type(node)), ast_node_get_line(node),
          ast_node_get_column(node), type_name(left).text);
  THROW(E_SEMANTIC_TYPE_ERROR,
        "operator '%s' at %zu:%zu cannot be applied to %s and %s",
        operator_name(ast_node_get_type(node)), ast_node_get_line(node),
        ast_node_get_column(node), type_name(left).text, type_name(right).text);
}

// Changes: new, the common type of two numeric operands; the Int side of a
// mixed pair is widened. Anything else is exit 6.
static Type unify_numbers(Ctx* ctx, AstNode* node, Type left, Type right) {
  if (!is_number(left) || !is_number(right))
    operand_error(ctx, node, left, right);
  if (same_type(left, right))
    return left;
  size_t int_side =
      left.base == AST_DATA_TYPE_INT ? AST_BINARY_LEFT : AST_BINARY_RIGHT;
  widen_node(ctx, ast_node_child(ctx, node, int_side));
  return PLAIN(AST_DATA_TYPE_DOUBLE);
}

// Changes: new, a binary operator: + - * / on numbers, + on Strings, relations
// on numbers or Strings, == != on the same type or numbers, && || on Booleans;
// anything else is exit 6.
static void check_binary(Ctx* ctx, Sema* sema, AstNode* node) {
  check_expr_children(ctx, sema, node, 0);
  AstNode* left = ast_node_child(ctx, node, AST_BINARY_LEFT);
  AstNode* right = ast_node_child(ctx, node, AST_BINARY_RIGHT);
  Type lt = expr_type(ctx, left);
  Type rt = expr_type(ctx, right);

  Type result = PLAIN(AST_DATA_TYPE_UNKNOWN);
  Type string = PLAIN(AST_DATA_TYPE_STRING);
  Type boolean = PLAIN(AST_DATA_TYPE_BOOLEAN);
  switch (ast_node_get_type(node)) {
    case AST_NODE_ADD:
      if (same_type(lt, string) && same_type(rt, string)) {
        result = string;
        break;
      }
      result = unify_numbers(ctx, node, lt, rt);
      break;
    case AST_NODE_SUB:
    case AST_NODE_MUL:
    case AST_NODE_DIV:
      result = unify_numbers(ctx, node, lt, rt);
      break;
    case AST_NODE_LT:
    case AST_NODE_GT:
    case AST_NODE_LE:
    case AST_NODE_GE:
      if (!(same_type(lt, string) && same_type(rt, string)))
        (void)unify_numbers(ctx, node, lt, rt);
      result = boolean;
      break;
    case AST_NODE_EQ:
    case AST_NODE_NEQ:
      if (lt.depth > 0 || rt.depth > 0)
        operand_error(ctx, node, lt, rt);
      if (!same_type(lt, rt))
        (void)unify_numbers(ctx, node, lt, rt);
      result = boolean;
      break;
    case AST_NODE_AND:
    case AST_NODE_OR:
      if (!same_type(lt, boolean) || !same_type(rt, boolean))
        operand_error(ctx, node, lt, rt);
      result = boolean;
      break;
    default:
      THROW(E_INTERNAL_ERROR, "unexpected binary operator at %zu:%zu",
            ast_node_get_line(node), ast_node_get_column(node));
  }
  set_node_type(node, result);
}

// Changes: new, whether the node is a list creation `List(...)` (before
// resolution, by the callee's name).
static bool is_list_creation(Ctx* ctx, const AstNode* node) {
  if (ast_node_get_type(node) != AST_NODE_CALL)
    return false;
  AstNode* callee = ast_node_child(ctx, node, AST_CALL_CALLEE);
  return ast_node_get_type(callee) == AST_NODE_IDENT &&
         ast_node_get_name(callee) != NULL &&
         strcmp(ast_node_get_name(callee), "List") == 0;
}

// Changes: new, whether the expression has no type of its own and needs an
// expected one: `List()`, a `List(...)` with any element that does, a
// `++` whose operands both do, an if expression with any branch that does.
// NOLINTNEXTLINE(misc-no-recursion)
static bool needs_expected(Ctx* ctx, const AstNode* node) {
  switch (ast_node_get_type(node)) {
    case AST_NODE_CALL: {
      if (!is_list_creation(ctx, node))
        return false;
      size_t count = ast_node_get_child_count(node);
      if (count == AST_CALL_FIRST_ARG)
        return true;
      for (size_t i = AST_CALL_FIRST_ARG; i < count; i++)
        if (needs_expected(ctx, ast_node_child(ctx, node, i)))
          return true;
      return false;
    }
    case AST_NODE_CONCAT:
      return needs_expected(ctx, ast_node_child(ctx, node, AST_BINARY_LEFT)) &&
             needs_expected(ctx, ast_node_child(ctx, node, AST_BINARY_RIGHT));
    case AST_NODE_BLOCK: {
      size_t count = ast_node_get_child_count(node);
      return count > 0 &&
             needs_expected(ctx, ast_node_child(ctx, node, count - 1));
    }
    case AST_NODE_IF:
      return (ast_node_get_flags(node) & (unsigned)AST_FLAG_EXPR) != 0 &&
             (needs_expected(ctx, ast_node_child(ctx, node, AST_IF_THEN)) ||
              needs_expected(ctx, ast_node_child(ctx, node, AST_IF_ELSE)));
    default:
      return false;
  }
}

// Changes: new, `a ++ b` (ADR-0007): both operands lists of the identical full
// type, the result that type; an operand that needs an expected type takes the
// outer one or the other operand's type. Anything else is exit 6.
// NOLINTNEXTLINE(misc-no-recursion)
static void check_concat(Ctx* ctx, Sema* sema, AstNode* node, Type expected) {
  AstNode* left = ast_node_child(ctx, node, AST_BINARY_LEFT);
  AstNode* right = ast_node_child(ctx, node, AST_BINARY_RIGHT);
  bool left_needs = needs_expected(ctx, left);
  bool right_needs = needs_expected(ctx, right);

  if (expected.depth > 0 || (left_needs && right_needs)) {
    check_expr_as(ctx, sema, left, expected);
    check_expr_as(ctx, sema, right, expected);
  } else if (left_needs ||
             (is_list_creation(ctx, left) && !is_list_creation(ctx, right))) {
    check_expr(ctx, sema, right);
    check_expr_as(ctx, sema, left, expr_type(ctx, right));
  } else {
    check_expr(ctx, sema, left);
    check_expr_as(ctx, sema, right, expr_type(ctx, left));
  }

  Type lt = expr_type(ctx, left);
  Type rt = expr_type(ctx, right);
  if (lt.depth == 0 || rt.depth == 0 || !same_type(lt, rt))
    operand_error(ctx, node, lt, rt);
  set_node_type(node, lt);
}

// Changes: new, a unary operator: NOT on Boolean, NEG on a number (keeps its
// type); anything else is exit 6.
static void check_unary(Ctx* ctx, Sema* sema, AstNode* node) {
  check_expr_children(ctx, sema, node, 0);
  AstNode* operand = ast_node_child(ctx, node, AST_UNARY_OPERAND);
  Type type = expr_type(ctx, operand);
  if (ast_node_get_type(node) == AST_NODE_NOT) {
    if (!same_type(type, PLAIN(AST_DATA_TYPE_BOOLEAN)))
      operand_error(ctx, node, type, type);
  } else if (!is_number(type)) {
    operand_error(ctx, node, type, type);
  }
  set_node_type(node, type);
}

// Changes: new, an interpolated string: every part is checked, any part type is
// accepted, the node is a String.
static void check_interp_string(Ctx* ctx, Sema* sema, AstNode* node) {
  check_expr_children(ctx, sema, node, 0);
  ast_node_set_data_type(node, AST_DATA_TYPE_STRING);
}

// Changes: new, the type of a call, read off the callee. An unchecked user
// function without a declared return type is checked on demand (pass state
// saved and restored); one already being checked is recursion, exit 6.
static Type call_result_type(Ctx* ctx, Sema* sema, const SymtableData* symbol) {
  AstNode* def = def_of_symbol(ctx, sema, symbol);
  if (def != NULL) {
    unsigned flags = ast_node_get_flags(def);
    if (!body_rule(ctx, def).declared) {
      if (flags & (unsigned)AST_FLAG_DEF_CHECKING) {
        AstNode* ident = ast_node_child(ctx, def, AST_DEF_IDENT);
        THROW(E_SEMANTIC_TYPE_ERROR,
              "function '%s' at %zu:%zu is used while its return type is being "
              "inferred, give it a declared return type",
              ast_node_get_name(ident), ast_node_get_line(ident),
              ast_node_get_column(ident));
      }
      if (!(flags & (unsigned)AST_FLAG_DEF_CHECKED)) {
        Sema saved = *sema;
        check_def(ctx, sema, def);
        *sema = saved;
      }
    }
  }
  return get_symbol_type(ctx, symbol);
}

// Changes: new, compares the checked arguments of a CALL with the callee's
// parameters from first_param on: wrong count or type is exit 5 (a list
// mismatch of a user function exit 6), Int widens to Double. A built-in's Unit
// parameter (print, toStr) takes any argument; List.range may omit its step.
static void check_call_arguments(Ctx* ctx,
                                 AstNode* node,
                                 const SymtableData* symbol,
                                 bool builtin,
                                 size_t first_param) {
  size_t argc = ast_node_get_child_count(node) - AST_CALL_FIRST_ARG;
  size_t takes = symbol->param_count - first_param;
  bool optional_step = builtin && symbol->ir_index == IR_FX_LIST_RANGE;
  if (optional_step && argc != takes && argc != takes - 1)
    THROW(E_SEMANTIC_ARGUMENT_ERROR,
          "call at %zu:%zu passes %zu argument(s) but List.range takes 2 or "
          "3",
          ast_node_get_line(node), ast_node_get_column(node), argc);
  if (!optional_step && argc != takes)
    THROW(E_SEMANTIC_ARGUMENT_ERROR,
          "call at %zu:%zu passes %zu argument(s) but the function takes %zu",
          ast_node_get_line(node), ast_node_get_column(node), argc, takes);

  for (size_t i = 0; i < argc; i++) {
    if (builtin && symbol->param_types[first_param + i] == IR_UNIT)
      continue;
    AstNode* argument = ast_node_child(ctx, node, AST_CALL_FIRST_ARG + i);
    Type expected = get_param_type(ctx, symbol, first_param + i);
    // A list mismatch is exit 6 for a user function only; a built-in keeps
    // exit 5 for any wrong type
    bool list =
        !builtin && (expected.depth > 0 || expr_type(ctx, argument).depth > 0);
    require_compatible(ctx, argument, expected,
                       list ? E_SEMANTIC_TYPE_ERROR : E_SEMANTIC_ARGUMENT_ERROR,
                       "an argument");
  }
}

// Changes: new, a List(...) CALL: each element is checked with the expected
// element type (ADR-0007). The CALL has the expected list type if every element
// fits it (an empty one too), else it is the list of the elements' common type
// (Int mixed with Double gives Double); no element or any other mix is exit 6.
// NOLINTNEXTLINE(misc-no-recursion)
static void check_list_creation(Ctx* ctx,
                                Sema* sema,
                                AstNode* node,
                                Type expected) {
  size_t count = ast_node_get_child_count(node);
  bool typed = expected.depth > 0;
  Type wanted = typed ? (Type){expected.base, expected.depth - 1} : NO_EXPECTED;
  for (size_t i = AST_CALL_FIRST_ARG; i < count; i++)
    check_expr_as(ctx, sema, ast_node_child(ctx, node, i), wanted);

  if (count == AST_CALL_FIRST_ARG) {
    if (!typed)
      THROW(E_SEMANTIC_TYPE_ERROR,
            "list at %zu:%zu has no elements and no expected type",
            ast_node_get_line(node), ast_node_get_column(node));
    set_node_type(node, expected);
    return;
  }

  bool fits = typed;
  for (size_t i = AST_CALL_FIRST_ARG; i < count && fits; i++)
    fits = is_compatible(expr_type(ctx, ast_node_child(ctx, node, i)), wanted);
  if (fits) {
    for (size_t i = AST_CALL_FIRST_ARG; i < count; i++) {
      AstNode* child = ast_node_child(ctx, node, i);
      if (!same_type(expr_type(ctx, child), wanted))
        widen_node(ctx, child);
    }
    set_node_type(node, expected);
    return;
  }

  Type element = expr_type(ctx, ast_node_child(ctx, node, AST_CALL_FIRST_ARG));
  bool has_double = false;
  bool has_int = false;
  for (size_t i = AST_CALL_FIRST_ARG; i < count; i++) {
    AstNode* child = ast_node_child(ctx, node, i);
    Type type = expr_type(ctx, child);
    has_int = has_int || same_type(type, PLAIN(AST_DATA_TYPE_INT));
    has_double = has_double || same_type(type, PLAIN(AST_DATA_TYPE_DOUBLE));
    if (!same_type(type, element) && !(is_number(type) && is_number(element)))
      THROW(E_SEMANTIC_TYPE_ERROR,
            "element at %zu:%zu is %s but the list elements are %s",
            ast_node_get_line(child), ast_node_get_column(child),
            type_name(type).text, type_name(element).text);
  }
  if (has_int && has_double) {
    element = PLAIN(AST_DATA_TYPE_DOUBLE);
    for (size_t i = AST_CALL_FIRST_ARG; i < count; i++) {
      AstNode* child = ast_node_child(ctx, node, i);
      if (same_type(expr_type(ctx, child), PLAIN(AST_DATA_TYPE_INT)))
        widen_node(ctx, child);
    }
  }
  set_node_type(node, (Type){element.base, element.depth + 1});
}

// Changes: new, the arguments of a CALL to a user function, each checked with
// the type of its parameter as expected type (an empty List() takes it); any
// other call checks them without one. Surplus arguments are left to the count
// check.
static void check_call_argument_exprs(Ctx* ctx,
                                      Sema* sema,
                                      AstNode* node,
                                      const SymtableData* symbol,
                                      bool builtin) {
  size_t count = ast_node_get_child_count(node);
  for (size_t i = AST_CALL_FIRST_ARG; i < count; i++) {
    size_t index = i - AST_CALL_FIRST_ARG;
    Type expected = !builtin && index < symbol->param_count
                        ? get_param_type(ctx, symbol, index)
                        : NO_EXPECTED;
    check_expr_as(ctx, sema, ast_node_child(ctx, node, i), expected);
  }
}

// Changes: new, an indexing: the callee is a list (else exit 6), the one
// argument an Int (else exit 5), the type the element type, one level less
// deep.
static void check_index(Ctx* ctx, Sema* sema, AstNode* node) {
  AstNode* callee = ast_node_child(ctx, node, AST_CALL_CALLEE);
  check_expr_children(ctx, sema, node, AST_CALL_FIRST_ARG);
  Type list = expr_type(ctx, callee);
  if (list.depth == 0)
    THROW(E_SEMANTIC_TYPE_ERROR,
          "call at %zu:%zu is on a value of type %s, only a list can be "
          "indexed",
          ast_node_get_line(node), ast_node_get_column(node),
          type_name(list).text);
  size_t argc = ast_node_get_child_count(node) - AST_CALL_FIRST_ARG;
  if (argc != 1)
    THROW(E_SEMANTIC_ARGUMENT_ERROR,
          "index at %zu:%zu takes one Int but gets %zu argument(s)",
          ast_node_get_line(node), ast_node_get_column(node), argc);
  require_compatible(ctx, ast_node_child(ctx, node, AST_CALL_FIRST_ARG),
                     PLAIN(AST_DATA_TYPE_INT), E_SEMANTIC_ARGUMENT_ERROR,
                     "an index");
  set_node_type(node, (Type){list.base, list.depth - 1});
}

// Changes: new, whether a visible variable has the name of the IDENT (the
// variable is tried first, Resolution in the glossary).
static bool names_visible_variable(const Sema* sema, const AstNode* ident) {
  const SymtableData* symbol =
      symtable_lookup(sema->scope, (char*)ast_node_get_name(ident), true);
  return symbol != NULL && symbol->symbol_type == SYMBOL_VARIABLE;
}

static const SymtableData* check_member(Ctx* ctx,
                                        Sema* sema,
                                        AstNode* node,
                                        bool called);

// Changes: new, a CALL: a variable or any other non-member callee is an
// indexing, a MEMBER callee a member call, otherwise the callee resolves among
// functions (exit 3); List(...) and toStr of a list are special-cased.
// NOLINTNEXTLINE(misc-no-recursion)
static void check_call(Ctx* ctx, Sema* sema, AstNode* node, Type expected) {
  AstNode* callee = ast_node_child(ctx, node, AST_CALL_CALLEE);
  if (ast_node_get_type(callee) == AST_NODE_MEMBER) {
    const SymtableData* member = check_member(ctx, sema, callee, true);
    if (member->param_count > 1) {
      check_expr_children(ctx, sema, node, AST_CALL_FIRST_ARG);
      check_call_arguments(ctx, node, member, true, 1);
      set_node_type(node, expr_type(ctx, callee));
      return;
    }
    check_index(ctx, sema, node);
    return;
  }
  if (ast_node_get_type(callee) != AST_NODE_IDENT ||
      names_visible_variable(sema, callee)) {
    check_expr(ctx, sema, callee);
    check_index(ctx, sema, node);
    return;
  }

  SymtableData* symbol = resolve_function(ctx, callee);
  bool builtin = def_of_symbol(ctx, sema, symbol) == NULL;
  if (builtin)
    mark_builtin(node);
  // A user function's ir_index is a function index, so only a built-in counts
  if (builtin && symbol->ir_index == IR_FX_LIST_CREATE) {
    check_list_creation(ctx, sema, node, expected);
    return;
  }
  check_call_argument_exprs(ctx, sema, node, symbol, builtin);
  check_call_arguments(ctx, node, symbol, builtin, 0);
  if (builtin && symbol->ir_index == IR_FX_TO_STR &&
      ast_node_get_child_count(node) > AST_CALL_FIRST_ARG &&
      expr_type(ctx, ast_node_child(ctx, node, AST_CALL_FIRST_ARG)).depth > 0)
    symbol = symtable_lookup(&ctx->global_symtable, "List.toString", false);
  if (builtin)
    ast_node_set_symbol(callee, symbol);
  set_node_type(node, call_result_type(ctx, sema, symbol));
}

// Changes: new, the owner part of a member key for a receiver type: "List" for
// any list.
static const char* receiver_name(Type receiver) {
  return receiver.depth > 0 ? "List" : data_type_name(receiver.base);
}

// Changes: new, looks up the member entry "<receiver type>.<member>" (ADR-0002)
// with the key on the C stack; a name too long for the buffer is not found.
static const SymtableData* lookup_member(Ctx* ctx,
                                         const char* receiver_type,
                                         const char* member) {
  char key[64];
  int length = snprintf(key, sizeof(key), "%s.%s", receiver_type, member);
  if (length < 0 || (size_t)length >= sizeof(key))
    return NULL;
  return symtable_lookup(&ctx->global_symtable, key, false);
}

// Changes: new, the member entry of a receiver's type; a list receiver is
// "List".
static const SymtableData* resolve_member(Ctx* ctx,
                                          Type receiver,
                                          const char* member) {
  return lookup_member(ctx, receiver_name(receiver), member);
}

// Changes: new, whether the member exists on another receiver type (a plain
// type, "List" or "Range"), telling "abc".toInt (exit 6) from x.foo (exit 3).
static bool member_exists_elsewhere(Ctx* ctx,
                                    Type receiver,
                                    const char* member) {
  for (size_t i = 0; i < TYPE_COUNT; i++)
    if (strcmp(TYPES[i].name, receiver_name(receiver)) != 0 &&
        lookup_member(ctx, TYPES[i].name, member) != NULL)
      return true;
  return lookup_member(ctx, "Range", member) != NULL;
}

// Changes: new, the type of a resolved member: a list member's ir_type encodes
// it (IR_ARRAY the receiver's own type, IR_UNIT its element type), any other
// is the type of its ir_type.
static Type member_result_type(Ctx* ctx,
                               const SymtableData* symbol,
                               Type receiver) {
  if (receiver.depth > 0 && symbol->ir_type == IR_ARRAY)
    return receiver;
  if (receiver.depth > 0 && symbol->ir_type == IR_UNIT)
    return (Type){receiver.base, receiver.depth - 1};
  return PLAIN(ir_to_data_type(ctx, symbol->ir_type));
}

// Changes: new, a MEMBER: resolved by its receiver's type, gets BUILTIN and the
// member's result type. A member of another receiver type is exit 6, an unknown
// name exit 3; a member with parameters is exit 5 unless called is set (the
// CALL around it checks the arguments). Returns the member's entry.
static const SymtableData* check_member(Ctx* ctx,
                                        Sema* sema,
                                        AstNode* node,
                                        bool called) {
  AstNode* receiver = ast_node_child(ctx, node, AST_MEMBER_RECEIVER);
  const char* member = ast_node_get_name(node);

  // A range value is legal only as the receiver of toList
  if (is_range(receiver)) {
    if (strcmp(member, "toList") != 0)
      THROW(E_SEMANTIC_TYPE_ERROR,
            "a range value at %zu:%zu has no member '%s', only toList",
            ast_node_get_line(receiver), ast_node_get_column(receiver), member);
    check_range(ctx, sema, receiver);
    const SymtableData* to_list =
        symtable_lookup(&ctx->global_symtable, "Range.toList", false);
    bind_builtin_member(node, to_list, get_symbol_type(ctx, to_list));
    return to_list;
  }

  check_expr_children(ctx, sema, node, 0);
  Type receiver_type = expr_type(ctx, receiver);

  const SymtableData* symbol = resolve_member(ctx, receiver_type, member);
  if (symbol == NULL) {
    if (member_exists_elsewhere(ctx, receiver_type, member))
      THROW(E_SEMANTIC_TYPE_ERROR, "no member '%s' on %s at %zu:%zu", member,
            type_name(receiver_type).text, ast_node_get_line(node),
            ast_node_get_column(node));
    THROW(E_SEMANTIC_UNDEFINED_ERROR, "undefined member '%s' at %zu:%zu",
          member, ast_node_get_line(node), ast_node_get_column(node));
  }
  if (!called && symbol->param_count > 1)
    THROW(E_SEMANTIC_ARGUMENT_ERROR,
          "member '%s' at %zu:%zu needs %zu argument(s) and a call", member,
          ast_node_get_line(node), ast_node_get_column(node),
          symbol->param_count - 1);
  bind_builtin_member(node, symbol,
                      member_result_type(ctx, symbol, receiver_type));
  return symbol;
}

// Changes: new, expression dispatch, one case per node kind that can be an
// expression; CALL, MEMBER and CONCAT reach the list rules.
static void check_expr(Ctx* ctx, Sema* sema, AstNode* node) {
  switch (ast_node_get_type(node)) {
    case AST_NODE_IDENT:
      check_ident(ctx, sema, node);
      break;
    case AST_NODE_INT_LIT:
    case AST_NODE_DOUBLE_LIT:
    case AST_NODE_STRING_LIT:
    case AST_NODE_BOOL_LIT:
    case AST_NODE_UNIT_LIT:
      check_literal(ctx, sema, node);
      break;
    case AST_NODE_ADD:
    case AST_NODE_SUB:
    case AST_NODE_MUL:
    case AST_NODE_DIV:
    case AST_NODE_EQ:
    case AST_NODE_NEQ:
    case AST_NODE_LT:
    case AST_NODE_GT:
    case AST_NODE_LE:
    case AST_NODE_GE:
    case AST_NODE_AND:
    case AST_NODE_OR:
      check_binary(ctx, sema, node);
      break;
    case AST_NODE_NOT:
    case AST_NODE_NEG:
      check_unary(ctx, sema, node);
      break;
    case AST_NODE_CONCAT:
      check_concat(ctx, sema, node, NO_EXPECTED);
      break;
    case AST_NODE_CALL:
      check_call(ctx, sema, node, NO_EXPECTED);
      break;
    case AST_NODE_MEMBER:
      (void)check_member(ctx, sema, node, false);
      break;
    case AST_NODE_INTERP_STRING:
      check_interp_string(ctx, sema, node);
      break;
    case AST_NODE_IF:
      check_if(ctx, sema, node);
      break;
    case AST_NODE_RANGE_TO:
    case AST_NODE_RANGE_UNTIL:
      THROW(E_SEMANTIC_TYPE_ERROR,
            "a range value at %zu:%zu is legal only as the receiver of toList "
            "or a for source",
            ast_node_get_line(node), ast_node_get_column(node));
    default:
      THROW(E_INTERNAL_ERROR, "unexpected expression node at %zu:%zu",
            ast_node_get_line(node), ast_node_get_column(node));
  }
}

// Changes: new, checks an expression with an expected type (ADR-0007), the one
// place the type is passed down: a CALL, a CONCAT and an if expression use it,
// any other node is checked as without one.
// NOLINTNEXTLINE(misc-no-recursion)
static void check_expr_as(Ctx* ctx, Sema* sema, AstNode* node, Type expected) {
  switch (ast_node_get_type(node)) {
    case AST_NODE_CALL:
      check_call(ctx, sema, node, expected);
      break;
    case AST_NODE_CONCAT:
      check_concat(ctx, sema, node, expected);
      break;
    case AST_NODE_IF:
      if (ast_node_get_flags(node) & (unsigned)AST_FLAG_EXPR) {
        ResultRule rule = if_expression_rule(expected);
        (void)check_if_node(ctx, sema, node, &rule);
        break;
      }
      check_expr(ctx, sema, node);
      break;
    default:
      check_expr(ctx, sema, node);
      break;
  }
}

// Changes: new, statement dispatch; any other node is checked as an expression.
static void check_stmt(Ctx* ctx, Sema* sema, AstNode* node) {
  switch (ast_node_get_type(node)) {
    case AST_NODE_BLOCK:
      (void)check_block(ctx, sema, node, NULL);
      break;
    case AST_NODE_VAL:
    case AST_NODE_VAR:
      check_val_var(ctx, sema, node);
      break;
    case AST_NODE_ASSIGN:
      check_assign(ctx, sema, node);
      break;
    case AST_NODE_RETURN:
      check_return(ctx, sema, node);
      break;
    case AST_NODE_WHILE:
      check_while(ctx, sema, node);
      break;
    case AST_NODE_FOR:
      check_for(ctx, sema, node);
      break;
    default:
      check_expr(ctx, sema, node);
      break;
  }
}

// Changes: new, checks the DEF's body BLOCK in its parameter scope under
// body_rule; an omitted return type becomes the inferred type.
static void check_body(Ctx* ctx, Sema* sema) {
  AstNode* body = ast_node_child(ctx, sema->def, AST_DEF_BODY);
  ResultRule rule = body_rule(ctx, sema->def);
  Type result = check_block(ctx, sema, body, &rule);
  if (rule.declared)
    return;

  AstNode* ident = ast_node_child(ctx, sema->def, AST_DEF_IDENT);
  SymtableData* symbol = symtable_lookup(
      &ctx->global_symtable, (char*)ast_node_get_name(ident), false);
  if (symbol == NULL)
    THROW(E_INTERNAL_ERROR, "function '%s' is not in the global scope",
          ast_node_get_name(ident));
  set_symbol_type(ctx, symbol, result);
}

// Changes: new, opens the parameter scope inside the global scope (also on
// demand), declares the read-only parameters (slots 0..n-1), checks the body
// while the DEF is marked as being checked; then a @main not returning Unit is
// exit 6.
static void check_def(Ctx* ctx, Sema* sema, AstNode* def) {
  AstNode* params = NULL;
  size_t param_count = def_param_list(ctx, def, &params);

  Symtable* outer = sema->scope;
  ast_node_set_flags(def,
                     ast_node_get_flags(def) | (unsigned)AST_FLAG_DEF_CHECKING);
  sema->scope = ast_node_attach_scope(ctx, def, &ctx->global_symtable);
  for (size_t i = 0; i < param_count; i++) {
    AstNode* param = ast_node_child(ctx, params, i);
    AstNode* ident = ast_node_child(ctx, param, AST_PARAM_IDENT);
    AstNode* type = ast_node_child(ctx, param, AST_PARAM_TYPE);
    declare_variable(ctx, sema, ident, annotation_type(ctx, type), true, i);
  }

  sema->def = def;
  sema->next_slot = param_count;
  check_body(ctx, sema);
  sema->def = NULL;
  sema->scope = outer;

  ast_node_set_flags(
      def, (ast_node_get_flags(def) & ~(unsigned)AST_FLAG_DEF_CHECKING) |
               (unsigned)AST_FLAG_DEF_CHECKED);
  AstNode* ident = ast_node_child(ctx, def, AST_DEF_IDENT);
  if ((ast_node_get_flags(def) & (unsigned)AST_FLAG_MAIN) &&
      !same_type(get_symbol_type(ctx, ast_node_get_symbol(ident)),
                 PLAIN(AST_DATA_TYPE_UNIT)))
    THROW(E_SEMANTIC_TYPE_ERROR,
          "@main function '%s' at %zu:%zu must return Unit",
          ast_node_get_name(ident), ast_node_get_line(ident),
          ast_node_get_column(ident));
}

// Changes: new, phase 2: checks every function in source order, skipping those
// already checked on demand.
static void check_functions(Ctx* ctx, Sema* sema) {
  size_t count = ast_node_get_child_count(sema->program);
  for (size_t i = 0; i < count; i++) {
    AstNode* def = ast_node_child(ctx, sema->program, i);
    if (ast_node_get_flags(def) & (unsigned)AST_FLAG_DEF_CHECKED)
      continue;
    check_def(ctx, sema, def);
  }
}

// Changes: new, whether any user call under node reaches target, directly or
// indirectly; each DEF is walked once per search, unreachable calls count too
// (PDF 2.3); an indexing has no function symbol.
// NOLINTNEXTLINE(misc-no-recursion)
static bool calls_reach(Ctx* ctx,
                        const Sema* sema,
                        AstNode* node,
                        const AstNode* target) {
  if (ast_node_get_type(node) == AST_NODE_CALL) {
    AstNode* callee = ast_node_child(ctx, node, AST_CALL_CALLEE);
    const SymtableData* symbol = ast_node_get_symbol(callee);
    AstNode* def = symbol == NULL || symbol->symbol_type != SYMBOL_FUNCTION
                       ? NULL
                       : def_of_symbol(ctx, sema, symbol);
    if (def == target)
      return true;
    if (def != NULL &&
        !(ast_node_get_flags(def) & (unsigned)AST_FLAG_DEF_CHECKING)) {
      ast_node_set_flags(
          def, ast_node_get_flags(def) | (unsigned)AST_FLAG_DEF_CHECKING);
      AstNode* body = ast_node_child(ctx, def, AST_DEF_BODY);
      if (calls_reach(ctx, sema, body, target))
        return true;
    }
  }
  size_t count = ast_node_get_child_count(node);
  for (size_t i = 0; i < count; i++) {
    AstNode* child = ast_node_child(ctx, node, i);
    if (calls_reach(ctx, sema, child, target))
      return true;
  }
  return false;
}

// Changes: new, phase 3: a function in direct or indirect recursion must
// declare its return type (PDF 2.3), exit 6.
static void check_recursion(Ctx* ctx, const Sema* sema) {
  size_t count = ast_node_get_child_count(sema->program);
  for (size_t i = 0; i < count; i++) {
    AstNode* def = ast_node_child(ctx, sema->program, i);
    if (body_rule(ctx, def).declared)
      continue;
    AstNode* body = ast_node_child(ctx, def, AST_DEF_BODY);
    bool recursive = calls_reach(ctx, sema, body, def);
    for (size_t j = 0; j < count; j++) {
      AstNode* other = ast_node_child(ctx, sema->program, j);
      ast_node_set_flags(
          other, ast_node_get_flags(other) & ~(unsigned)AST_FLAG_DEF_CHECKING);
    }
    if (recursive) {
      AstNode* ident = ast_node_child(ctx, def, AST_DEF_IDENT);
      THROW(E_SEMANTIC_TYPE_ERROR,
            "recursive function '%s' at %zu:%zu needs a declared return type",
            ast_node_get_name(ident), ast_node_get_line(ident),
            ast_node_get_column(ident));
    }
  }
}

// Changes: new, the public entry point, runs the phases over ctx->ast with the
// context's global symtable as the global scope.
void semantics_analyze(Ctx* ctx) {
  if (ctx->ast == NULL || ast_node_get_type(ctx->ast) != AST_NODE_PROGRAM)
    THROW(E_INTERNAL_ERROR, "semantic analysis needs a PROGRAM in ctx->ast");

  Sema sema = {
      .program = ctx->ast,
      .scope = &ctx->global_symtable,
      .def = NULL,
      .next_slot = 0,
  };
  insert_members(ctx, &sema);
  collect_functions(ctx, &sema);
  check_functions(ctx, &sema);
  check_recursion(ctx, &sema);
}
